#include <iostream>
#include <vector>
int main() {
    std::vector<int> v{1,2,3,4,5};
    int k = 3, sum = 0, best = 0;
    for (int i = 0; i < (int)v.size(); ++i) {
        sum += v[i];
        if (i >= k) sum -= v[i-k];
        if (i >= k-1) best = std::max(best, sum);
    }
    std::cout << best << "\n";
}

