#include <iostream>
#include <numeric>
#include <vector>
struct DSU{std::vector<int> p;DSU(int n):p(n){std::iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}bool unite(int a,int b){a=find(a);b=find(b);if(a==b)return false;p[b]=a;return true;}};
int main(){DSU d(4);std::cout<<d.unite(0,1)<<" "<<d.unite(0,1)<<"\n";}

#include <functional>
#include <iostream>
#include <queue>
#include <vector>
int main(){using P=std::pair<int,int>;std::vector<std::vector<P>> g(3);g[0]={{1,4},{2,1}};g[2]={{1,2}};std::vector<int>d(3,1e9);d[0]=0;std::priority_queue<P,std::vector<P>,std::greater<P>>pq;pq.push({0,0});while(!pq.empty()){auto[du,u]=pq.top();pq.pop();if(du!=d[u])continue;for(auto[v,w]:g[u])if(d[v]>du+w){d[v]=du+w;pq.push({d[v],v});}}std::cout<<d[1]<<"\n";}

